create function public.portal_register_order_document(p_order_key text,p_product_id uuid,p_title text,p_file_name text,p_path text,p_note text default '') returns uuid language plpgsql security invoker set search_path='' as $$ declare d uuid; begin d:=public.portal_register_product_document(p_product_id,p_title,p_file_name,p_path,p_note); perform public.link_order_drawing(p_order_key,d,false);return d;end $$; revoke all on function public.portal_register_order_document(text,uuid,text,text,text,text) from public,anon; grant execute on function public.portal_register_order_document(text,uuid,text,text,text,text) to authenticated;